<script lang="ts">import{api,percent,number,stamp,iconPath,type Row}from'../lib/api';import{tr}from'../lib/i18n';import Icon from './Icon.svelte';export let settings:Row={};export let quota:Row={};export let preview=false;export let onsave:(r:Row)=>Promise<void>=async()=>{};export let onerror:(e:any)=>void=()=>{};function remaining(w:Row){return number(w?.remaining_percent)??(number(w?.used_percent)===null?null:100-Number(w.used_percent))}async function action(name:string){try{await api('DesktopAction',name)}catch(e){onerror(e)}}$: style=settings.visual_style??'classic';$: scope=settings.quota_scope??'auto';$: windows=scope==='week'||scope==='auto'&&!quota.primary?[['周额度',quota.secondary??{}]]:[['5 小时额度',quota.primary??{}],['周额度',quota.secondary??{}]];</script>
{#if !preview&&settings.dock_edge&&settings.dock_edge!=='none'}
<div class="floating docked" class:vertical={['left','right'].includes(settings.dock_edge)} style="--wails-draggable:drag" style:background={settings.background_transparent?`rgba(var(--floating-rgb),${(100-Number(settings.background_opacity??70))/100})`:'rgb(var(--floating-rgb))'}><button class="quiet dock-brand" aria-label={tr('打开主窗口')} onclick={()=>action('show-main')}><img src={iconPath(settings.app_icon??'main')} alt="Codexio"/></button>{#each windows as [label,w]}{@const n=remaining(w)}<div class="dock-quota"><span>{label==='周额度'?tr('周'):tr('5 小时')}</span><strong style:color={n!==null&&n<20?'var(--danger)':'var(--tokens)'}>{percent(n)}</strong><div class="meter"><div style:width={`${Math.max(0,Math.min(100,n??0))}%`} style:background={n!==null&&n<20?'var(--danger)':'var(--tokens)'}></div></div></div>{/each}<button class="quiet dock-close" aria-label={tr('隐藏悬浮窗')} onclick={()=>action('hide-floating')}><Icon name="close" size={13}/></button></div>
{:else}
<div class={`floating ${style}`} class:preview style:background={settings.background_transparent?`rgba(var(--floating-rgb),${(100-Number(settings.background_opacity??70))/100})`:'rgb(var(--floating-rgb))'} style:border-color={settings.show_border===false?'transparent':settings.border_color??'#8AB4F8'}><div class="floating-brand" style="--wails-draggable:drag"><img src={iconPath(settings.app_icon??'main')} alt="Codexio"/><span>Codexio</span>{#if !preview}<button class="quiet" aria-label={tr('打开主窗口')} onclick={()=>action('show-main')}><Icon name="overview" size={15}/></button>{/if}</div><div class="floating-quotas">{#each windows as [label,w]}{@const n=remaining(w)}<div class="floating-quota" class:low={n!==null&&n<20}>{#if ['rings','orb'].includes(style)}<svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="41" fill="none" stroke="var(--raised)" stroke-width="7"/><circle cx="50" cy="50" r="41" fill="none" stroke={n!==null&&n<20?'var(--danger)':'var(--tokens)'} stroke-width="7" pathLength="100" stroke-dasharray={`${Math.max(0,Math.min(100,n??0))} 100`} transform="rotate(-90 50 50)"/><text x="50" y="56" text-anchor="middle" font-size="20" fill="currentColor">{percent(n)}</text></svg>{:else}<strong>{percent(n)}</strong>{/if}<span>{tr(label)}</span>{#if !['minimal','orb'].includes(style)}<div class="meter"><div style:width={`${Math.max(0,Math.min(100,n??0))}%`} style:background={n!==null&&n<20?'var(--danger)':'var(--tokens)'}></div></div><small>{tr('重置')} {stamp(w.resets_at)}</small>{/if}</div>{/each}</div>{#if quota.error}<small class="error">{quota.error}</small>{/if}{#if !preview}<div class="floating-actions"><button class="quiet" onclick={()=>action('show-main')}>{tr('打开主窗口')}</button><button class="quiet" onclick={()=>action('hide-floating')}>{tr('隐藏悬浮窗')}</button><select aria-label={tr('显示模式')} value={settings.display_mode??'top'} onchange={e=>onsave({display_mode:e.currentTarget.value})}>{#each [['top','始终置顶'],['bottom','桌面底层'],['tray','仅托盘']] as [v,l]}<option value={v}>{tr(l)}</option>{/each}</select><select aria-label={tr('贴边停靠')} value={settings.dock_edge??'none'} onchange={e=>onsave({dock_edge:e.currentTarget.value})}>{#each [['none','不贴边'],['top','顶部'],['bottom','底部'],['left','左侧'],['right','右侧']] as [v,l]}<option value={v}>{tr(l)}</option>{/each}</select></div>{/if}</div>
{/if}
